SELECT T_A.* , T_A.NAME_ENC AS NAME , T_A.TELEPHONE_NUMBER_ENC AS TELEPHONE_NUMBER , T_A.ADDRESS_ENC AS ADDRESS , T_A.ADDRESS_DETAIL_ENC AS ADDRESS_DETAIL FROM ( SELECT SHIPMENT_ID , SELLER_ID , ADDRESS_NAME , NAME AS NAME_ENC , TELEPHONE_NUMBER AS TELEPHONE_NUMBER_ENC , ZIPCODE , ADDRESS AS ADDRESS_ENC , ADDRESS_DETAIL AS ADDRESS_DETAIL_ENC , DEFAULT_ADDRESS_FLAG , SHIPPING , SHIPPING_FREE_AMOUNT , SHIPPING_EXTRA_CHARGE1 , SHIPPING_EXTRA_CHARGE2 , SHIPMENT_GROUP_CODE , CREATED_DATE , UPDATED_DATE FROM OP_SHIPMENT
WHERE SELLER_ID = #{value}
ORDER BY SHIPMENT_ID DESC ) T_A

SELECT T_A.* , T_A.NAME_ENC AS NAME , T_A.TELEPHONE_NUMBER_ENC AS TELEPHONE_NUMBER , T_A.ADDRESS_ENC AS ADDRESS , T_A.ADDRESS_DETAIL_ENC AS ADDRESS_DETAIL FROM ( SELECT SHIPMENT_ID , SELLER_ID , ADDRESS_NAME , NAME AS NAME_ENC , TELEPHONE_NUMBER AS TELEPHONE_NUMBER_ENC , ZIPCODE , ADDRESS AS ADDRESS_ENC , ADDRESS_DETAIL AS ADDRESS_DETAIL_ENC , DEFAULT_ADDRESS_FLAG , SHIPPING , SHIPPING_FREE_AMOUNT , SHIPPING_EXTRA_CHARGE1 , SHIPPING_EXTRA_CHARGE2 , SHIPMENT_GROUP_CODE , CREATED_DATE , UPDATED_DATE FROM OP_SHIPMENT
AND SHIPMENT_ID = #{shipmentId}
AND SELLER_ID = #{sellerId}
AND DEFAULT_ADDRESS_FLAG = #{defaultAddressFlag}
ORDER BY SHIPMENT_ID DESC LIMIT 1 ) T_A

mapper.update:
UPDATE OP_SHIPMENT SET
	DEFAULT_ADDRESS_FLAG = 'N'
WHERE SHIPMENT_ID != #{shipmentId} AND SELLER_ID = #{sellerId}
